exercise.referenceSolution:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct IntVec {
    int *data;
    size_t length;
    size_t capacity;
};

void vec_init(struct IntVec *v) {
    v->data = NULL;
    v->length = 0;
    v->capacity = 0;
}

int vec_reserve(struct IntVec *v, size_t min_capacity) {
    if (min_capacity <= v->capacity) {
        return 0;
    }
    size_t capacity = v->capacity ? v->capacity : 4;
    while (capacity < min_capacity) {
        capacity *= 2;
    }
    int *bigger = realloc(v->data, capacity * sizeof *bigger);
    if (bigger == NULL) {
        return -1;
    }
    v->data = bigger;
    v->capacity = capacity;
    return 0;
}

int vec_push(struct IntVec *v, int value) {
    if (vec_reserve(v, v->length + 1) != 0) {
        return -1;
    }
    v->data[v->length++] = value;
    return 0;
}

void vec_free(struct IntVec *v) {
    free(v->data);
    vec_init(v);
}

int main(void) {
    struct IntVec v;
    vec_init(&v);
    char cmd[8];
    while (scanf("%7s", cmd) == 1) {
        if (strcmp(cmd, "push") == 0) {
            int x;
            scanf("%d", &x);
            if (vec_push(&v, x) != 0) {
                vec_free(&v);
                return 1;
            }
        } else if (strcmp(cmd, "pop") == 0 || strcmp(cmd, "top") == 0) {
            if (v.length == 0) {
                printf("empty\n");
            } else if (cmd[0] == 'p') {
                printf("%d\n", v.data[--v.length]);
            } else {
                printf("%d\n", v.data[v.length - 1]);
            }
        } else {
            printf("%zu\n", v.length);
        }
    }
    vec_free(&v);
    return 0;
}

