int vec_shrink(struct IntVec *v) {
    if (v->length == 0) {
        free(v->data);
        v->data = NULL;
        v->capacity = 0;
        return 0;
    }
    int *smaller = realloc(v->data, v->length * sizeof *smaller);
    if (smaller == NULL) {
        return -1;
    }
    v->data = smaller;
    v->capacity = v->length;
