#include <stdio.h>

struct Vec {
    int data[8];
    int length;
};

void remove_at(struct Vec *v, int index) {
    for (int i = index; i + 1 < v->length; i++) {
        v->data[i] = v->data[i + 1];
    }
    v->length--;
}

int main(void) {
    struct Vec v = {{4, 8, 15, 16, 23, 42}, 6};
    remove_at(&v, 1);
    remove_at(&v, 3);
    for (int i = 0; i < v.length; i++) {
        printf("%d ", v.data[i]);
    }
    printf("\n");
    return 0;
}
